 const emitted=new Set(),routes=[];for(const r of kept){if(!core.has(r.section)){routes.push(r);continue;}if(emitted.has(r.section))continue;emitted.add(r.section);const ordinary=kept.filter(x=>x.section===r.section&&x.number==null),formal=D.tasks.filter(t=>t.section===r.section);
  ordinary.forEach(x=>routes.push(x));for(const t of formal){const e=G.exercises.find(e=>e.id===t.id);if(!e)continue;const route=kept.find(x=>x.number===e.number&&x.pages.includes(e.pages[0]))||{anchor:e.pages[0],pages:e.pages,section:e.section,kind:'content',number:e.number,group:e.group};const phase=t.classroom_phase.toUpperCase(),title=route.label?.replace(/^Ex\.\s*\d+\s*·\s*/,'')||e.titles[0];routes.push({...route,label:'Ex. '+e.number+' · '+phase+' · '+title});}
  kept.filter(x=>x.section===r.section&&x.number!=null&&!formal.some(t=>G.exercises.find(e=>e.id===t.id)?.pages.includes(x.anchor))).forEach(x=>routes.push(x));
 }
 S.routes=routes;S.routeMap={};routes.forEach((r,i)=>r.pages.forEach(p=>S.routeMap[String(p)]=i));
