 for(const g of S.groups){g.assignments=g.assignments.filter(p=>!window.SCHOOL_EXCLUDED_PAGES.has(p));if(g.exercises.length){for(const p of g.assignments)S.assignmentRedirect[String(p)]=g.exercises[0].pages[0];}}
